// Independent synthetic acceptance baselines for v0.14.0 (build e34b2f5).
// Values are fixed rather than regenerated by the implementation under test.
// Revenue: sum of 9 months of price * quantity; cost: configured % of revenue.
// Finance: independent single-product simulation; fees rounded per unit.
// Forecast: exact linear continuation of synthetic history, not market prediction.
const assert = require("node:assert/strict");
const starter = require("../core/starter.js");
const sales = require("../core/sales.js");
const finance = require("../core/finance.js");
const operations = require("../core/operations.js");
const forecast = require("../core/forecast.js");
const connect = require("../core/connect.js");
const expected = {
  "retail": {
    "revenue_cents": 3651300,
    "cost_cents": 2482884,
    "result_cents": 1168416,
    "margin_pct": 32,
    "orders": 27,
    "quantity": 837,
    "ticket_cents": 135233,
    "top_product": "Mochila",
    "finance_result_cents": -57360,
    "finance_break_even_units": 173,
    "forecast_cents": [
      529700,
      554500,
      579300
    ],
    "capacity": 210,
    "bottleneck": "Expedição"
  },
  "services": {
    "revenue_cents": 14679000,
    "cost_cents": 7045920,
    "result_cents": 7633080,
    "margin_pct": 52,
    "orders": 27,
    "quantity": 540,
    "ticket_cents": 543667,
    "top_product": "Treinamento",
    "finance_result_cents": 218700,
    "finance_break_even_units": 11,
    "forecast_cents": [
      2421000,
      2579000,
      2737000
    ],
    "capacity": 210,
    "bottleneck": "Revisão"
  },
  "industry": {
    "revenue_cents": 7767000,
    "cost_cents": 5747580,
    "result_cents": 2019420,
    "margin_pct": 26,
    "orders": 27,
    "quantity": 1107,
    "ticket_cents": 287667,
    "top_product": "Kit de montagem",
    "finance_result_cents": -107300,
    "finance_break_even_units": 274,
    "forecast_cents": [
      1068000,
      1109000,
      1150000
    ],
    "capacity": 210,
    "bottleneck": "Inspeção"
  },
  "restaurant": {
    "revenue_cents": 2527200,
    "cost_cents": 1819584,
    "result_cents": 707616,
    "margin_pct": 28,
    "orders": 27,
    "quantity": 1431,
    "ticket_cents": 93600,
    "top_product": "Prato executivo",
    "finance_result_cents": -20000,
    "finance_break_even_units": 225,
    "forecast_cents": [
      334800,
      345600,
      356400
    ],
    "capacity": 210,
    "bottleneck": "Entrega"
  },
  "ecommerce": {
    "revenue_cents": 6930900,
    "cost_cents": 4574394,
    "result_cents": 2356506,
    "margin_pct": 34,
    "orders": 27,
    "quantity": 864,
    "ticket_cents": 256700,
    "top_product": "Kit presente",
    "finance_result_cents": -47590,
    "finance_break_even_units": 140,
    "forecast_cents": [
      1004100,
      1050900,
      1097700
    ],
    "capacity": 210,
    "bottleneck": "Despacho"
  }
};
let count = 0;
function check(label, fn) { fn(); count++; console.log("PASS " + label); }
check("scenario catalog matches baselines", () => assert.deepEqual(starter.list().map(x=>x.id).sort(), Object.keys(expected).sort()));
for (const [id, e] of Object.entries(expected)) {
  const data = starter.build(id);
  check(id + " Insights reference totals", () => {
    const rows = connect.parse(data.insights).rows;
    const revenue = rows.reduce((sum,row)=>sum+Math.round(Number(row[1])*100),0);
    const cost = rows.reduce((sum,row)=>sum+Math.round(Number(row[2])*100),0);
    assert.equal(rows.length,9);
    assert.equal(revenue,e.revenue_cents);
    assert.equal(cost,e.cost_cents);
    assert.equal(revenue-cost,e.result_cents);
    assert.equal((revenue-cost)*100/revenue,e.margin_pct);
  });
  check(id + " Sales reference totals", () => {
    const s = sales.summarize(sales.parse(data.sales));
    assert.equal(s.revenue_cents,String(e.revenue_cents));
    assert.equal(s.orders,e.orders);
    assert.equal(s.quantity,String(e.quantity));
    assert.equal(s.average_order_cents,String(e.ticket_cents));
    assert.equal(s.products[0].name,e.top_product);
  });
  check(id + " Finance reference simulation", () => {
    const f = finance.simulate(data.finance);
    assert.equal(f.result_cents,String(e.finance_result_cents));
    assert.equal(f.break_even_units,String(e.finance_break_even_units));
  });
  check(id + " Operations reference capacity", () => {
    const o = operations.summarize(operations.parse(data.operations));
    assert.equal(o.capacity,e.capacity);
    assert.deepEqual(o.bottlenecks,[e.bottleneck]);
  });
  check(id + " Forecast reference projection", () => {
    const f = forecast.analyze(forecast.parse(data.forecast),3,"trend");
    assert.deepEqual(f.future.map(x=>x.month),["2026-10","2026-11","2026-12"]);
    assert.deepEqual(f.future.map(x=>Math.round(x.value*100)),e.forecast_cents);
  });
}
console.log(count + " synthetic acceptance reference checks passed");
